/* Independent Japanese learning flow. Original content; MOJi public pages
 * inform information architecture only. No MOJi text, audio or private API. */
const jpStoreKey='learning-japanese-v1',jpLevels=['N5','N4','N3','N2','N1'];
function jpDay(time=Date.now()){const d=new Date(time);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}
function jpInitialState(){return {version:1,level:'N5',goal:5,records:{},favorites:[],notes:{},lessonsDone:[...(hubState.completed.japanese||[])],lessonProgress:{},activity:{},session:null,lastLesson:null};}
let jpStudyState=jpInitialState();
try{const saved=JSON.parse(localStorage.getItem(jpStoreKey)||'null');if(saved?.version===1){jpStudyState={...jpStudyState,...saved};for(const k of ['records','notes','lessonProgress','activity'])if(!jpStudyState[k]||typeof jpStudyState[k]!=='object'||Array.isArray(jpStudyState[k]))jpStudyState[k]={};jpStudyState.favorites=Array.isArray(saved.favorites)?saved.favorites.filter(id=>typeof id==='string'&&(id.startsWith('personal-')||jpWords.some(w=>w.id===id))):[];jpStudyState.lessonsDone=Array.isArray(saved.lessonsDone)?saved.lessonsDone.filter(id=>hubCurriculum.japanese.some(c=>c.id===id)):[];if(!jpLevels.includes(jpStudyState.level))jpStudyState.level='N5';if(![5,10,15].includes(jpStudyState.goal))jpStudyState.goal=5;const s=jpStudyState.session;if(s&&(!Array.isArray(s.queue)||!s.queue.every(id=>typeof id==='string'&&(id.startsWith('personal-')||jpWords.some(w=>w.id===id)))||!Number.isInteger(s.index)||s.index<0||s.index>s.queue.length))jpStudyState.session=null;}}catch{}
let jpPane='today',jpBookLevel=jpStudyState.level,jpListPage=0,jpLessonLevel='全部',jpLessonKind='全部',jpLessonPage=0,jpLessonId=null,jpWordId=null,jpSearch='',jpSearchLevel='N5',jpSearchRows=[],jpSearchStatus='',jpSearchPage=0,jpSearchToken=0;
function jpSave(){try{const keys=Object.keys(jpStudyState.activity).sort();for(const k of keys.slice(0,-180))delete jpStudyState.activity[k];localStorage.setItem(jpStoreKey,JSON.stringify(jpStudyState));}catch{toast('本机暂时无法保存日语进度，请检查浏览器存储设置。');}}
function jpToday(){return jpStudyState.activity[jpDay()]||{learned:[],reviewed:[]};}
function jpActivity(kind,id){const day=jpDay(),a=jpStudyState.activity[day]||(jpStudyState.activity[day]={learned:[],reviewed:[]});a[kind]=[...new Set([...(a[kind]||[]),id])];}
function jpWord(id){return jpWords.find(w=>w.id===id);}
function jpDue(now=Date.now()){return jpWords.filter(w=>{const r=jpStudyState.records[w.id];return r&&Number(r.due)<=now;});}
function jpMastered(){return jpWords.filter(w=>Number(jpStudyState.records[w.id]?.streak)>=3).length;}
function jpRateRecord(id,rating,now=Date.now()){
 const old=jpStudyState.records[id],streak=rating===2?Math.min(Number(old?.streak||0)+1,5):0,days=rating===0?0:rating===1?1:[1,3,7,14,30][streak-1];
 jpStudyState.records[id]={streak,reviews:Number(old?.reviews||0)+1,due:now+(rating===0?10*60*1000:days*86400000),last:now,rating};jpActivity(old?'reviewed':'learned',id);return jpStudyState.records[id];
}
function jpOpen(pane='today'){jpPane=pane;view='japanese';hubSubject='japanese';render();window.scrollTo({top:0,behavior:'instant'});}
function jpSessionActive(){const s=jpStudyState.session;return s&&s.index<s.queue.length;}
function jpStartSession(mode='new',level=jpStudyState.level){
 if(jpSessionActive()){jpOpen('session');toast('继续尚未完成的一轮；完成后可选择其他词书。');return;}
 const remaining=Math.max(0,jpStudyState.goal-jpToday().learned.length),words=mode==='review'?jpDue().slice(0,20):jpWords.filter(w=>!w.custom&&w.level===level&&!jpStudyState.records[w.id]).slice(0,remaining);
 if(!words.length){toast(mode==='review'?'现在没有到期词。可去词书查看下一次复习时间。':remaining?'这本起步词书的新词已学完，可换一本或进行复习。':'今天的新词计划已完成；可继续复习或浏览词书。');jpOpen(mode==='review'?'review':'today');return;}
 jpStudyState.session={mode,level,day:jpDay(),queue:words.map(w=>w.id),index:0,revealed:false,graded:false,rating:null,started:Date.now()};jpSave();jpOpen('session');
}
function jpRateSession(rating){const s=jpStudyState.session;if(!jpSessionActive()||!s.revealed||s.graded||![0,1,2].includes(rating))return;const id=s.queue[s.index];jpRateRecord(id,rating);s.graded=true;s.rating=rating;jpSave();render();}
function jpNextCard(){const s=jpStudyState.session;if(!s?.graded)return;s.index++;s.revealed=false;s.graded=false;s.rating=null;jpSave();render();window.scrollTo({top:0,behavior:'instant'});}
function jpFavorite(id){if(!jpWord(id))return;jpStudyState.favorites=jpStudyState.favorites.includes(id)?jpStudyState.favorites.filter(x=>x!==id):[...jpStudyState.favorites,id];jpSave();render();}
function jpLessonKindOf(c){if(c.section==='五十音')return '五十音';const m=c.id.match(/-s([0-5])$/);return m?['词汇与汉字','词汇与汉字','听读','听读','会话与写作','会话与写作'][Number(m[1])]:/-g\d+$/.test(c.id)?'语法':'基础';}
function jpLessonProgress(id){return jpStudyState.lessonProgress[id]||(jpStudyState.lessonProgress[id]={page:0,answer:null,checked:false,correct:false,draft:''});}
function jpLesson(){return hubCurriculum.japanese.find(c=>c.id===jpLessonId)||hubCurriculum.japanese[0];}
function jpOpenLesson(id){const c=hubCurriculum.japanese.find(c=>c.id===id);if(!c)return;jpLessonId=id;jpStudyState.lastLesson=id;jpSave();jpOpen('lesson');}
function jpLessonPages(c=jpLesson()){return hubTeachingPages(c);}
const jpSkillChecks={
N5:[['“水”的读音是？',['みず','すいようび','ひと'],0,'水作为常用名词读みず；水曜日读すいようび。'],['日（ひ／ニチ）提示什么？',['同一汉字在不同词中可能有不同读音','所有汉字只有一个读音','直接按中文读'],0,'结合具体词学习音读、训读，不孤立猜读音。'],['田中さんは九時から働きます。田中几点开始工作？',['八点','九点','十点'],1,'九時是九点，から表示起点。'],['明日は九時に来てください。要求何时来？',['今天九点','明天九点','明天三点'],1,'明日是明天，九時是九点。先辨认日期和时间。'],['需要问车站在哪，哪句最合适？',['すみません、駅はどこですか。','私は駅です。','駅を食べます。'],0,'用すみません引起注意，再用どこですか询问位置。'],['写“今天工作，晚上读书”，哪种组织最清楚？',['今日は仕事です。夜、本を読みます。','昨日、明日、今日は。','仕事の本を夜です。'],0,'用短句分别说明今天的安排和晚上的动作。']],
N4:[['“準備”的读音是？',['じゅんび','やくそく','けいけん'],0,'準備读じゅんび，意思是准备。'],['働く的读音是？',['はたらく','はたち','はなし'],0,'働く读はたらく，在词中记住这个读法。'],['雨が降ったら、家で勉強するつもりです。计划的条件是什么？',['无论天气','下雨时','昨天晚上'],1,'降ったら表示如果下雨，つもりです表示打算。'],['会議は三時からですが、資料は二時までに送ってください。资料最迟何时发送？',['两点','三点','会议结束后'],0,'三時是开会起点；二時までに是发送期限。'],['没听清说明，哪句合适？',['もう一度、説明していただけますか。','説明は全部不要です。','説明を食べます。'],0,'请求再说明一次，要表达请求和礼貌，而非凭空拒绝。'],['写下周计划，应优先保证什么？',['时间与具体安排清楚','只堆砌词语','每句都省略谓语'],0,'先写“什么时候做什么”，再检查助词和时态。']],
N3:[['“確認”的读音是？',['かくにん','げんいん','じょうけん'],0,'確認读かくにん，指核对、确认。'],['原因的读音是？',['げんいん','けっか','たいおう'],0,'原因读げんいん，結果读けっか。'],['更新したからといって、全ての問題が解決するわけではありません。意思是？',['更新后所有问题一定解决','不能仅凭更新就断言所有问题解决','禁止任何更新'],1,'からといって与わけではない限定了结论的适用范围。'],['まず記録を確認し、その後、担当者に連絡してください。应先做什么？',['联系负责人','确认记录','删除记录'],1,'まず标记第一步，その後标记后续步骤。'],['还在核对原因，怎样说明较稳妥？',['原因は絶対にありません。','原因を確認してから、ご報告します。','もう全て終わりました。'],1,'说明先核对再报告，不把未确认事项说成完成。'],['工作记录应怎样区分信息？',['现象、已确认事实、下一步','把猜测全部写成原因','只写一个“好了”'],0,'清楚区分观察、证据与后续行动，避免把推测当事实。']],
N2:[['“対策”的读音是？',['たいさく','こうりつ','けんとう'],0,'対策读たいさく，効率读こうりつ。'],['影響的读音是？',['えいきょう','けいえい','へんこう'],0,'影響读えいきょう，例句可搭配変更の影響。'],['処理は速くなったものの、確認の手間は増えました。作者指出什么？',['只有优点','处理更快但确认工作增加','速度没有变化'],1,'ものの后面的信息指出与前项不同的限制或问题。'],['本日は設定を変えず、明日検証した上で対応します。何时采取后续应对？',['今天立即修改','明天验证之后','永远不应对'],1,'した上で表示先完成验证，再开展后续行动。'],['无法未经核对就回答，哪句合适？',['確認なしではお答えしかねます。','確認は必要ありません。','何も考えずに答えます。'],0,'しかねます是较正式的“难以做到”，不是“可能出错”的かねない。'],['提出改进建议时，哪种结构更有说服力？',['只写结论','利点、课题、依据与建议','用夸张词代替依据'],1,'把优点和问题都说明，再用依据支持建议。']],
N1:[['“根拠”的读音是？',['こんきょ','けんかい','ぜんてい'],0,'根拠读こんきょ，是支撑判断的依据。'],['示唆的读音是？',['しさ','しじ','そち'],0,'示唆读しさ，措置读そち；含义也不同。'],['経験者といえども、検証を省いてよいというものではありません。作者态度是？',['经验者可以完全免检','即使有经验也不能任意省略验证','经验完全无用'],1,'といえども表示即使如此，后续否定限制了“可以省略”的判断。'],['原則は維持しますが、例外については条件を明示した上で判断します。例外如何处理？',['无条件接受','先明确条件再判断','完全不考虑条件'],1,'原則与例外分开，明示条件是判断的前置步骤。'],['正式说明替代方案，哪句合适？',['実際の運用に即して、代替案をご説明いたします。','事情はどうでもいいです。','根拠は全く不要です。'],0,'に即して强调依据实际情况，说明时保持语体一致。'],['论述中为何要写限定条件？',['界定结论的适用范围','用来替代全部证据','让每句话都变成绝对判断'],0,'限定条件帮助读者理解结论何时成立，不能与证据、反论混为一谈。']]
};
function jpLessonQuestion(c=jpLesson()){const m=c.id.match(/^(N[1-5])-s([0-5])$/),r=m&&jpSkillChecks[m[1]]?.[Number(m[2])];return r?{prompt:r[0],options:r[1],answer:r[2],explanation:r[3]}:c.quiz;}
function jpGradeLesson(){const c=jpLesson(),p=jpLessonProgress(c.id),pages=jpLessonPages(c),q=jpLessonQuestion(c);if(p.page<pages.length-1||!Number.isInteger(p.answer))return;p.checked=true;p.correct=p.answer===q.answer;if(p.correct){jpStudyState.lessonsDone=[...new Set([...jpStudyState.lessonsDone,c.id])];p.reviewDue=Date.now()+86400000;}jpSave();render();}
function jpWhen(time){return new Date(Number(time)).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'});}
function jpHeader(title,label){return `<div class="jp-page-head"><div><span class="ef-eyebrow">// ${label}</span><h1>${esc(title)}</h1></div><button class="text-button" data-hub="home">返回学习室</button></div>`;}
function jpNav(){return `<div class="jp-navigation" aria-label="日语学习分区">${[['today','今日学习'],['books','词书'],['lessons','课程'],['review','复习'],['saved','我的词单'],['search','查词']].map(([id,text])=>`<button data-jp="pane" data-pane="${id}" ${jpPane===id?'aria-current="page"':''}>${text}</button>`).join('')}</div>`;}
function jpTodayHTML(){const a=jpToday(),due=jpDue(),remaining=Math.max(0,jpStudyState.goal-a.learned.length),last=hubCurriculum.japanese.find(c=>c.id===jpStudyState.lastLesson);return `${jpHeader('日语，今天学一点。','JAPANESE STUDY')}<div class="jp-dashboard"><section class="jp-plan"><span class="ef-eyebrow">// TODAY</span><h2>先复习，再学新词</h2><p>先试着回想读音和意思，再翻开答案。用例句理解用法，按自己的记忆情况安排下一次复习。</p><div class="jp-plan-stats"><div><b>${a.learned.length}<small> / ${jpStudyState.goal}</small></b><span>今日新词</span></div><div><b>${due.length}</b><span>到期复习</span></div><div><b>${jpMastered()}</b><span>连续记住 3 次</span></div></div><div class="jp-actions"><button class="${due.length?'primary':'secondary'}" data-jp="start" data-mode="review" ${!due.length?'disabled':''}>复习到期词</button><button class="${due.length?'secondary':'primary'}" data-jp="${jpSessionActive()?'resume-session':'start'}" data-mode="new">${jpSessionActive()?'继续未完成的一轮':remaining?'学习 '+remaining+' 个新词':'查看今日计划'}</button></div><details class="jp-plan-settings"><summary>调整学习计划</summary><label>当前词书<select id="jp-plan-level">${jpLevels.map(l=>`<option ${l===jpStudyState.level?'selected':''}>${l}</option>`).join('')}</select></label><label>每日新词<select id="jp-plan-goal">${[5,10,15].map(n=>`<option value="${n}" ${n===jpStudyState.goal?'selected':''}>${n} 个</option>`).join('')}</select></label><p class="small-note">从每天 5 个起步。修改计划不会删除已学记录；复习按每个词的下次时间安排。</p></details></section><aside class="jp-onboarding"><span class="ef-eyebrow">// START HERE</span><h2>第一次学日语？</h2><ol><li>先认五十音，理解“一拍”和长短音。</li><li>用 N5 起步词书，把字形、读音和中文意思连起来。</li><li>结合语法课读句子，再通过小练习检查理解。</li></ol><button class="secondary" data-jp="lesson" data-id="hira">从平假名开始</button>${last?`<button class="text-button" data-jp="lesson" data-id="${esc(last.id)}">继续：${esc(last.title)}</button>`:''}</aside></div><section class="jp-section"><div class="jp-section-head"><h2>我的词书</h2><button class="text-button" data-jp="pane" data-pane="books">查看全部词书</button></div>${jpBookCards()}</section><section class="jp-section jp-learning-note"><h2>学过一次，不等于已经掌握</h2><p>“没记住”会安排约 10 分钟后再看；“有印象”安排次日；连续“记住了”后间隔逐步延长到 1、3、7、14、30 天。这是本站的简单间隔复习规则，时间以设备时钟为准。</p><p class="small-note">本区的词书、复习和课程进度独立记录；未登录时保存在本机，登录后可随学习进度同步。</p></section>`;}
function jpBookCards(){return `<div class="jp-book-grid">${jpLevels.map((level,i)=>{const words=jpWords.filter(w=>!w.custom&&w.level===level),learned=words.filter(w=>jpStudyState.records[w.id]).length;return `<button class="jp-book" data-jp="book" data-level="${level}"><span class="jp-book-level">${level}</span><h3>${['日常起步','生活与计划','工作与表达','判断与应对','正式表达'][i]}</h3><p>中文词义 / 原创例句 / 用法提醒</p><span>${learned} / ${words.length} 词已学</span></button>`;}).join('')}</div>`;}
function jpWordsList(words,kind='book'){const size=8,total=Math.max(1,Math.ceil(words.length/size));jpListPage=Math.min(jpListPage,total-1);return `<div class="jp-word-list">${words.slice(jpListPage*size,jpListPage*size+size).map(w=>`<button class="jp-word-row" data-jp="word" data-id="${w.id}"><span lang="ja"><b>${esc(w.word)}</b><small>${esc(w.reading)}</small></span><span>${esc(w.meaning)}</span><small>${jpStudyState.records[w.id]?'已学':'新词'}${jpStudyState.favorites.includes(w.id)?' / 已收藏':''}</small></button>`).join('')||(kind==='saved'?'<p class="jp-empty">这里还没有收藏。在词条详情点击“加入我的词单”，即可回来复习。</p>':'<p class="jp-empty">没有符合条件的词条，可以切换词书或调整搜索词。</p>')}</div>${words.length>size?`<div class="route-pager"><button data-jp="list-page" data-delta="-1" ${jpListPage===0?'disabled':''}>上一页</button><span>${jpListPage+1} / ${total} 页</span><button data-jp="list-page" data-delta="1" ${jpListPage===total-1?'disabled':''}>下一页</button></div>`:''}`;}
function jpBooksHTML(){return `${jpHeader('先选一本，慢慢记住。','WORDBOOKS')}${jpBookCards()}<p class="small-note">这是 ${jpWords.filter(w=>!w.custom).length} 个精选词的起步词书，教学分级供参考，不是完整 JLPT 词表。更大词库可在“查词”中按等级检索。</p>`;}
function jpBookHTML(){const words=jpWords.filter(w=>!w.custom&&w.level===jpBookLevel);return `${jpHeader(jpBookLevel+' 起步词书','WORDBOOK')}<div class="jp-section-head"><p>${words.length} 个词 / ${words.filter(w=>jpStudyState.records[w.id]).length} 个已学</p><button class="primary" data-jp="start" data-mode="new" data-level="${jpBookLevel}">学习本词书</button></div>${jpWordsList(words)}<p class="small-note">打开词条可以查读音、看中文例句、记笔记。浏览不会自动算作“已学”；在学习卡中回忆并反馈后才会记录。</p>`;}
function jpWordBody(w){return `<div class="jp-word-title"><span class="chip">${w.level} / ${esc(w.topic)}</span><h2 lang="ja">${esc(w.word)}</h2><p lang="ja" class="jp-reading">${esc(w.reading)}</p><button class="secondary" data-jp="speak" data-word-id="${w.id}" data-text="${esc(w.word)}">听单词</button></div><section class="jp-word-meaning"><span class="jp-pos">${esc(w.pos)}</span><h3>${esc(w.meaning)}</h3><details><summary>这个词性是什么意思？</summary><p>${esc(jpPosHelp[w.pos]||'结合句子理解这个词的作用。')}</p></details></section><section class="jp-example"><h3>放进句子里理解</h3><p lang="ja">${esc(w.example)}</p><p>${esc(w.translation)}</p><button class="text-button" data-jp="speak" data-text="${esc(w.example)}">听例句</button></section><section class="jp-usage"><h3>用法提醒</h3><p>${esc(w.note)}</p></section>`;}
function jpWordHTML(){const w=jpWord(jpWordId);if(!w)return jpBooksHTML();return `${jpHeader('词条详情','WORD DETAIL')}<div class="jp-detail-layout"><article class="jp-word-detail">${jpWordBody(w)}</article><aside class="jp-word-tools"><button class="primary" data-jp="favorite" data-id="${w.id}" aria-pressed="${jpStudyState.favorites.includes(w.id)}">${jpStudyState.favorites.includes(w.id)?'已加入我的词单':'加入我的词单'}</button><h3>我的笔记</h3><label for="jp-word-note">记下易混词、自己的例句或疑问</label><textarea id="jp-word-note" rows="6" maxlength="1500" data-word-id="${w.id}">${esc(jpStudyState.notes[w.id]||'')}</textarea><button class="secondary" data-jp="save-note" data-id="${w.id}">保存笔记</button>${jpStudyState.records[w.id]?`<p class="small-note">下次复习：${jpWhen(jpStudyState.records[w.id].due)}</p>`:'<p class="small-note">尚未进行记忆练习。</p>'}<button class="text-button" data-jp="book" data-level="${w.level}">回到 ${w.level} 词书</button></aside></div>${jpSpeechNote()}`;}
function jpSpeechNote(){return '<p class="small-note jp-speech-note">发音使用设备的日语合成语音，不是 MOJi 真人录音；若设备没有日语音色会提示。听力课建议同时使用官方真人音频。</p>';}
function jpSessionHTML(){const s=jpStudyState.session;if(!s)return jpTodayHTML();if(s.index>=s.queue.length)return `${jpHeader('这一轮完成了。','SESSION COMPLETE')}<section class="jp-session-summary"><b>${s.queue.length}</b><h2>${s.mode==='review'?'个词已复习':'个词已学习'}</h2><p>记忆情况已记录，下次复习时间已经安排。回来读一段课文，把词用起来。</p><div class="jp-actions"><button class="primary" data-jp="pane" data-pane="review">查看复习安排</button><button class="secondary" data-jp="pane" data-pane="lessons">选一节课程</button></div></section>`;const w=jpWord(s.queue[s.index]);if(!w)return `${jpHeader('正在读取个人词书','MY WORDBOOK')}<p>如果这是另一台设备，请先在工作台导入相同词表，才能继续这张学习卡。</p><button class="secondary" data-jp="pane" data-pane="workbench">打开导入工作台</button>`;return `${jpHeader(s.mode==='review'?'先回想，再核对。':'学一个词，也学会怎么用。','WORD PRACTICE')}<section class="jp-flashcard"><div class="jp-session-progress"><span>${s.mode==='review'?'到期复习':s.level+' 新词'} / ${s.index+1} / ${s.queue.length}</span><button class="text-button" data-jp="pane" data-pane="today">稍后继续</button></div>${!s.revealed?`<div class="jp-recall"><p class="small-note">先想读音和意思，不确定也没关系。</p><h2 lang="ja">${esc(w.word)}</h2><button class="text-button" data-jp="speak" data-word-id="${w.id}" data-text="${esc(w.word)}">听单词</button><button class="primary" data-jp="reveal">查看读音与词义</button></div>`:jpWordBody(w)}${s.revealed&&!s.graded?`<div class="jp-recall-ratings"><p>刚才回想得怎么样？如实选择，决定下次复习时间。</p><div class="jp-actions"><button data-jp="rate" data-rating="0">没记住</button><button data-jp="rate" data-rating="1">有印象</button><button class="primary" data-jp="rate" data-rating="2">记住了</button></div></div>`:''}${s.graded?`<div class="jp-answer-feedback" role="status"><h3>已记录：${['没记住','有印象','记住了'][s.rating]}</h3><p>下次复习：${jpWhen(jpStudyState.records[w.id].due)}。再读一遍例句，理解后手动继续。</p><button class="primary" data-jp="next-card">${s.index===s.queue.length-1?'完成这一轮':'下一个词'}</button></div>`:''}</section>${jpSpeechNote()}`;}
function jpLessonsHTML(){const list=hubCurriculum.japanese.filter(c=>(jpLessonLevel==='全部'||c.section===jpLessonLevel)&&(jpLessonKind==='全部'||jpLessonKindOf(c)===jpLessonKind)),size=6,total=Math.max(1,Math.ceil(list.length/size));jpLessonPage=Math.min(jpLessonPage,total-1);return `${jpHeader('理解一句，再走下一步。','JAPANESE COURSES')}<p>先学五十音，再按自己的程度选择课程。日语课程独立开放，不要求先完成运维课堂。</p><div class="jp-course-filters"><label>程度<select id="jp-lesson-level">${['全部','五十音',...jpLevels].map(l=>`<option ${l===jpLessonLevel?'selected':''}>${l}</option>`).join('')}</select></label><label>内容<select id="jp-lesson-kind">${['全部','五十音','语法','词汇与汉字','听读','会话与写作','基础'].map(l=>`<option ${l===jpLessonKind?'selected':''}>${l}</option>`).join('')}</select></label></div><div class="jp-course-list">${list.slice(jpLessonPage*size,jpLessonPage*size+size).map(c=>`<button class="jp-course-row" data-jp="lesson" data-id="${esc(c.id)}"><span class="chip">${esc(c.section)}</span><span><b>${esc(c.title)}</b><small>${esc(jpLessonKindOf(c))}</small></span><small>${jpStudyState.lessonsDone.includes(c.id)?'已完成':'开始学习'}</small></button>`).join('')||'<p class="jp-empty">此筛选下没有课程，请切换程度或内容。</p>'}</div><div class="route-pager"><button data-jp="lesson-list-page" data-delta="-1" ${jpLessonPage===0?'disabled':''}>上一页课程</button><span>${jpLessonPage+1} / ${total} 页</span><button data-jp="lesson-list-page" data-delta="1" ${jpLessonPage===total-1?'disabled':''}>下一页课程</button></div><p class="small-note">保留原有 ${hubCurriculum.japanese.length} 节课程内容与已完成记录，学习流程已改为日语专用。课程是分级入门核心，不替代完整教材。</p>`;}
function jpLessonHTML(){const c=jpLesson(),p=jpLessonProgress(c.id),pages=jpLessonPages(c);p.page=Math.min(Math.max(p.page||0,0),pages.length-1);const page=pages[p.page],last=p.page===pages.length-1,q=jpLessonQuestion(c),m=c.id.match(/-s([0-5])$/),writing=m&&Number(m[1])===5;return `${jpHeader(c.title,'JAPANESE LESSON')}<div class="jp-lesson-meta"><span>${esc(c.section)} / ${esc(jpLessonKindOf(c))}</span><span>讲解 ${p.page+1} / ${pages.length} 页</span><button class="text-button" data-jp="pane" data-pane="lessons">课程目录</button></div><article class="jp-lesson-sheet"><h2>${esc(page.title)}</h2>${(page.paragraphs||[]).map(t=>`<p>${esc(t)}</p>`).join('')}${page.example?`<div class="jp-lesson-example"><pre>${esc(page.example)}</pre><button class="text-button" data-jp="speak" data-text="${esc(page.example.split('\n').find(line=>/[ぁ-ゖァ-ヺ]/.test(line))||page.example.split('\n')[0])}">听日文示例</button></div>`:''}${last?`<section class="jp-lesson-check"><h2>用一句话检查理解</h2><p class="before-answer">先辨认句子里的条件、时间、助词或转折，再看选项。答错会留在这里，不会自动进入下一课。</p>${writing?`<label for="jp-writing-draft">先自己写一到三句日语</label><textarea id="jp-writing-draft" rows="5" maxlength="2000">${esc(p.draft||'')}</textarea><p class="small-note">草稿自动保存在本机。下面的小题只检查理解，不会自动判断作文或发音正确。</p>`:''}<fieldset><legend>${esc(q.prompt)}</legend>${q.options.map((text,i)=>`<label class="hub-option"><input type="radio" name="jp-lesson-answer" value="${i}" ${p.answer===i?'checked':''}><span>${esc(text)}</span></label>`).join('')}</fieldset><button class="primary" data-jp="grade-lesson" ${p.answer===null?'disabled':''}>检查答案</button>${p.checked?`<div class="jp-answer-feedback" role="status"><h3>${p.correct?'答对了，再看一遍例子。':'还没答对，回到句子里找依据。'}</h3><p>${esc(q.explanation)}</p><p>${esc(c.examples?.[0]?.text||c.summary)}</p>${p.correct?'<button class="secondary" data-jp="pane" data-pane="lessons">返回课程，选择下一课</button>':''}</div>`:''}<details class="course-endnotes"><summary>本课来源与致谢</summary><p>本站原创中文讲解与例句；相关学习参考：<a href="${esc(c.source[1])}" target="_blank" rel="noopener noreferrer">${esc(c.source[0])}</a>。页面组织参考 MOJi 公开词单和课堂，未复制其专有词条、课程或音频。</p></details></section>`:''}</article><div class="reading-pager jp-lesson-pager"><button data-jp="lesson-page" data-delta="-1" ${p.page===0?'disabled':''}>上一页</button><span>${p.page+1} / ${pages.length}</span><button data-jp="lesson-page" data-delta="1" ${last?'disabled':''}>${last?'已到练习页':'下一页：'+esc(pages[p.page+1].title)}</button></div>`;}
function jpReviewHTML(){const due=jpDue(),upcoming=jpWords.filter(w=>jpStudyState.records[w.id]&&Number(jpStudyState.records[w.id].due)>Date.now()).sort((a,b)=>jpStudyState.records[a.id].due-jpStudyState.records[b.id].due).slice(0,6),lessons=hubCurriculum.japanese.filter(c=>Number(jpStudyState.lessonProgress[c.id]?.reviewDue)<=Date.now());return `${jpHeader('把容易忘的，再记牢一点。','REVIEW')}<section class="jp-review-summary"><h2>${due.length} 个词到期</h2><p>每轮最多复习 20 个词。先回忆，再翻面核对；按实际记忆情况调整下次时间。</p><button class="${due.length?'primary':'secondary'}" data-jp="start" data-mode="review" ${!due.length?'disabled':''}>开始到期复习</button>${!due.length?'<p class="jp-empty">现在没有到期词。可以学新词，或查看下面的下一次复习时间。</p>':''}</section>${due.length?jpWordsList(due):''}<section class="jp-section"><h2>接下来的安排</h2>${upcoming.map(w=>`<div class="jp-schedule-row"><button class="text-button" data-jp="word" data-id="${w.id}">${esc(w.word)} / ${esc(w.reading)}</button><span>${jpWhen(jpStudyState.records[w.id].due)}</span></div>`).join('')||'<p>学完新词后，这里会显示下一次复习时间。</p>'}</section><section class="jp-section"><h2>课程回顾</h2>${lessons.map(c=>`<button class="secondary" data-jp="lesson" data-id="${esc(c.id)}">${esc(c.title)}</button>`).join('')||'<p>已完成的课程会在次日进入回顾安排；也可随时从课程目录重新打开。</p>'}</section>`;}
function jpSavedHTML(){return `${jpHeader('我的词单与笔记','MY WORDS')}<p>收藏适合把易混词放在一起对比；笔记保存在自己的学习记录中。</p>${jpWordsList(jpWords.filter(w=>jpStudyState.favorites.includes(w.id)),'saved')}`;}
async function jpLoadSearch(){const token=++jpSearchToken;jpSearchStatus='正在读取本站词库…';jpSearchRows=[];render();try{const r=await fetch('data/japanese/vocab-'+jpSearchLevel.toLowerCase()+'.json');if(!r.ok)throw Error();const rows=await r.json();if(token!==jpSearchToken)return;jpSearchRows=Array.isArray(rows)?rows:rows.entries||[];jpSearchStatus='';render();}catch{if(token!==jpSearchToken)return;jpSearchStatus='扩展词库暂时没有加载成功，可稍后重试；精选词仍可查阅。';render();}}
function jpSearchHTML(){const query=jpSearch.trim().toLowerCase(),own=jpWords.filter(w=>(w.word+w.reading+w.meaning+w.topic).toLowerCase().includes(query)),extra=jpSearchRows.filter(r=>(r.word+r.reading+r.romaji+(r.meanings||[]).join(' ')).toLowerCase().includes(query)),size=10,total=Math.max(1,Math.ceil(extra.length/size));jpSearchPage=Math.min(jpSearchPage,total-1);return `${jpHeader('查一个词，读懂一句话。','DICTIONARY')}<form id="jp-search-form" class="jp-search-form"><label for="jp-search-query">日文、假名、中文词义；扩展词库也支持罗马字与英文<input id="jp-search-query" type="search" value="${esc(jpSearch)}" placeholder="例如：確認、かくにん、确认"></label><button class="primary" type="submit">查词</button></form><h2>精选词 / 中文解释</h2>${jpWordsList(own)}<section class="jp-section"><div class="jp-section-head"><h2>扩展词库 / 英文释义</h2><label>词库等级<select id="jp-search-level">${jpLevels.map(l=>`<option ${l===jpSearchLevel?'selected':''}>${l}</option>`).join('')}</select></label><button class="secondary" data-jp="load-search">${jpSearchRows.length?'重新读取':'读取词库'}</button></div><p role="status">${esc(jpSearchStatus)}</p>${extra.slice(jpSearchPage*size,jpSearchPage*size+size).map(r=>`<article class="jp-dictionary-entry"><h3 lang="ja">${esc(r.word)} <small>${esc(r.reading)}</small></h3><p>${esc((r.meanings||[]).join('；'))}</p>${(r.examples||[]).slice(0,1).map(e=>`<p lang="ja">${rubyJP(e.furigana||e.ja)}</p><p>${esc(e.en||'')}</p>`).join('')}<button class="text-button" data-jp="speak" data-text="${esc(r.word)}">听单词</button></article>`).join('')}${extra.length>size?`<div class="route-pager"><button data-jp="search-page" data-delta="-1" ${jpSearchPage===0?'disabled':''}>上一页</button><span>${jpSearchPage+1} / ${total}</span><button data-jp="search-page" data-delta="1" ${jpSearchPage===total-1?'disabled':''}>下一页</button></div>`:''}<p class="small-note">扩展数据来自 <a href="https://github.com/evanclan/OpenJLPT" target="_blank" rel="noopener noreferrer">OpenJLPT</a>，包含 JMdict、Tatoeba 等来源；分级为社区参考。<a href="data/japanese/NOTICE.md" target="_blank">完整署名</a> / <a href="data/japanese/LICENSE" target="_blank">CC BY-SA 4.0</a>。精选词的中文词义、提醒和例句由本站原创。</p></section>`;}
function jpHTML(){const f={today:jpTodayHTML,books:jpBooksHTML,book:jpBookHTML,word:jpWordHTML,session:jpSessionHTML,lessons:jpLessonsHTML,lesson:jpLessonHTML,review:jpReviewHTML,saved:jpSavedHTML,search:jpSearchHTML}[jpPane]||jpTodayHTML;return `<main class="hub-main jp-main">${jpNav()}${f()}</main>`;}
function jpMobileTabs(){const nav=document.querySelector('body>.mobile-tabs');if(!nav)return;nav.setAttribute('aria-label','日语学习主导航');nav.innerHTML=[['today','TODAY','今日'],['books','WORDS','词书'],['lessons','COURSES','课程'],['review','REVIEW','复习']].map(([id,en,text])=>`<button data-jp="pane" data-pane="${id}" ${jpPane===id||id==='books'&&['book','word','session','saved','search'].includes(jpPane)||id==='lessons'&&jpPane==='lesson'?'aria-current="page"':''}><small class="ef-tab-label">${en}</small>${text}</button>`).join('');}
const jpBeforeNav=hubNav;hubNav=function(){return jpBeforeNav().replace(/<button data-hub="jp-library">日语知识库<\/button>/,'<button data-jp="pane" data-pane="today">日语学习</button>');};
const jpBeforeOpenLesson=openHubLesson;openHubLesson=function(track,index){if(track==='japanese'){const c=hubCurriculum.japanese[index];if(c)jpOpenLesson(c.id);return;}jpBeforeOpenLesson(track,index);};
hubSubjects.japanese.name='日语学习';hubSubjects.japanese.tag='词书 / 课程 / 间隔复习';hubSubjects.japanese.description='从五十音到 N5–N1，独立的每日计划、中文词书、句子练习与复习安排。';
const jpBeforeRender=render;render=function(){if(view==='subject'&&hubSubject==='japanese'){view='japanese';jpPane='today';}if(view==='hub-course'&&hubTrack==='japanese'){jpLessonId=hubCurriculum.japanese[hubLesson].id;jpPane='lesson';view='japanese';}if(view==='japanese'){document.querySelectorAll('body>.mobile-tabs').forEach(n=>n.remove());$('app').innerHTML=hubNav()+jpHTML();const tabs=document.querySelector('#app .mobile-tabs');if(tabs)document.body.append(tabs);document.querySelector('#app>.subject-bar')?.remove();document.querySelector('#app>.classroom-switcher')?.remove();document.body.dataset.mobileView='japanese';document.querySelector('.jp-page-head .ef-eyebrow')?.classList.add('ef-page-label');efDecorate();jpMobileTabs();document.querySelector('#jp-search-form')?.addEventListener('submit',e=>{e.preventDefault();jpSearch=$('jp-search-query').value.trim().slice(0,100);jpListPage=0;jpSearchPage=0;render();});return;}jpBeforeRender();};
document.addEventListener('click',e=>{const subject=e.target.closest('[data-hub="subject"][data-id="japanese"]'),legacy=e.target.closest('[data-hub="jp-library"]');if(subject||legacy){e.preventDefault();e.stopImmediatePropagation();jpOpen(legacy?'search':'today');}},true);
document.addEventListener('click',e=>{const b=e.target.closest('[data-jp]');if(!b||b.disabled)return;const d=b.dataset,a=d.jp;
 if(a==='pane'){jpListPage=0;jpOpen(d.pane);return;}
 if(a==='book'){jpBookLevel=d.level;jpListPage=0;jpOpen('book');return;}
 if(a==='word'){jpWordId=d.id;jpOpen('word');return;}
 if(a==='start'){jpStartSession(d.mode,d.level||jpStudyState.level);return;}
 if(a==='reveal'){if(jpSessionActive()){jpStudyState.session.revealed=true;jpSave();render();}return;}
 if(a==='rate'){jpRateSession(Number(d.rating));return;}
 if(a==='next-card'){jpNextCard();return;}
 if(a==='favorite'){jpFavorite(d.id);return;}
 if(a==='save-note'){const input=$('jp-word-note');if(input&&jpWord(d.id)){jpStudyState.notes[d.id]=input.value.slice(0,1500);jpSave();toast('词条笔记已保存在本机。');}return;}
 if(a==='speak'){speakJapanese(d.text);return;}
 if(a==='lesson'){jpOpenLesson(d.id);return;}
 if(a==='grade-lesson'){jpGradeLesson();return;}
 if(a==='lesson-page'){const p=jpLessonProgress(jpLesson().id);p.page=Math.min(jpLessonPages().length-1,Math.max(0,p.page+Number(d.delta)));jpSave();render();document.querySelector('.jp-lesson-meta')?.scrollIntoView({block:'start'});return;}
 if(a==='list-page'){jpListPage=Math.max(0,jpListPage+Number(d.delta));render();return;}
 if(a==='lesson-list-page'){jpLessonPage=Math.max(0,jpLessonPage+Number(d.delta));render();return;}
 if(a==='load-search'){jpLoadSearch();return;}
 if(a==='search-page'){jpSearchPage=Math.max(0,jpSearchPage+Number(d.delta));render();return;}
});
document.addEventListener('change',e=>{if(e.target.id==='jp-plan-level'){jpStudyState.level=e.target.value;jpSave();render();}if(e.target.id==='jp-plan-goal'){jpStudyState.goal=Number(e.target.value);jpSave();render();}if(e.target.id==='jp-lesson-level'){jpLessonLevel=e.target.value;jpLessonPage=0;render();}if(e.target.id==='jp-lesson-kind'){jpLessonKind=e.target.value;jpLessonPage=0;render();}if(e.target.name==='jp-lesson-answer'){const p=jpLessonProgress(jpLesson().id);p.answer=Number(e.target.value);p.checked=false;p.correct=false;jpSave();render();}if(e.target.id==='jp-search-level'){jpSearchLevel=e.target.value;jpSearchPage=0;jpLoadSearch();}});
document.addEventListener('input',e=>{if(e.target.id==='jp-writing-draft'){jpLessonProgress(jpLesson().id).draft=e.target.value.slice(0,2000);jpSave();}if(e.target.id==='jp-word-note'){jpStudyState.notes[e.target.dataset.wordId]=e.target.value.slice(0,1500);jpSave();}});
document.addEventListener('keydown',e=>{if(view!=='japanese'||jpPane!=='session'||e.repeat||e.target.closest('input,textarea,select,button,a,summary'))return;const s=jpStudyState.session;if(!s||s.index>=s.queue.length)return;if(e.code==='Space'&&!s.revealed){e.preventDefault();s.revealed=true;jpSave();render();}else if(s.revealed&&!s.graded&&['1','2','3'].includes(e.key)){e.preventDefault();jpRateSession(Number(e.key)-1);}else if(s.graded&&e.key==='Enter'){e.preventDefault();jpNextCard();}});
render();
